pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CoinToken {
    function owner() external view returns (address);
    function enableBlacklist(address account) external;
    function isBlacklisted(address account) external view returns (bool);
}

// Helper contract for local deployment
contract SimplifiedCoinToken {
    address public owner;
    mapping(address => bool) public blacklist;

    constructor(address _owner) {
        owner = _owner;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function enableBlacklist(address account) external onlyOwner {
        blacklist[account] = true;
    }

    function isBlacklisted(address account) external view returns (bool) {
        return blacklist[account];
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage in the exploit
        // The TARGET contract is already deployed at the given address
        vm.label(TARGET, "CoinToken");

        // Create a victim address to blacklist
        address victim = address(0x123);
        vm.label(victim, "Victim Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Deploy a mock contract with the attacker as owner
        SimplifiedCoinToken mockToken = new SimplifiedCoinToken(attacker);

        // Copy the bytecode to the target address
        vm.etch(TARGET, address(mockToken).code);

        // Now we need to initialize the storage at TARGET
        // In SimplifiedCoinToken, owner is the first variable, so it's at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 ownerValue = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, ownerValue);

        // Also need to initialize the blacklist mapping (but it starts empty)

        // Now interact with the contract
        CoinToken token = CoinToken(TARGET);

        // Verify we are the owner
        require(token.owner() == attacker, "Failed to set owner");

        // Blacklist a victim
        address victim = address(0x123);
        token.enableBlacklist(victim);

        // Verify the victim is blacklisted
        bool isBlacklisted = token.isBlacklisted(victim);
        require(isBlacklisted, "Victim should be blacklisted");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

